#!/usr/bin/env bash
# Campaign 24: find a setting where the oracle routine is healthy at x10 with 44 users, since campaign 21's first arm churned at 70 GB (results/campaign24/DECISIONS.md). Each probe runs past the 55-65 min where that arm fell over.
#   host: docker exec -d sglang_hicache bash -c 'nohup bash /sgl-workspace/sglang/agent_cache/frozen/oracle_scripts_staging/c24_probe/c24.sh >> /sgl-workspace/sglang/agent_cache/results/campaign24/launcher.log 2>&1'
# Do not edit this file or agent_cache/scripts/ while it runs.
set -uo pipefail
AC=/sgl-workspace/sglang/agent_cache
CD=$AC/results/campaign24
STAGED=$AC/frozen/oracle_scripts_staging/c22_ladder/start_server.sh
SCRIPT=$AC/scripts/start_server.sh
ORIGINAL_SHA=d60cad9c9e228c6ad8c4453217eb69dc7c2d9853abc96935167214486a7c80a8
JIT_ENGINE=$AC/frozen/engine_table_20261101/python
V2_ENGINE=$AC/frozen/engine_5df71c4bf0_v2/python
mkdir -p "$CD"; touch "$CD/manifest.txt"
if pgrep -f '^bash run_compare.sh' > /dev/null; then echo "C24 STOP $(date -u +%FT%TZ): run_compare.sh is running"; exit 1; fi
cd "$AC/scripts" || exit 1
CUR=$(sha256sum "$SCRIPT" | cut -d' ' -f1); NEW=$(sha256sum "$STAGED" | cut -d' ' -f1)
if [ "$CUR" = "$ORIGINAL_SHA" ]; then
  cat "$STAGED" > "$SCRIPT"; echo "C24 installed the new arms in scripts/start_server.sh"
elif [ "$CUR" != "$NEW" ]; then
  echo "C24 STOP $(date -u +%FT%TZ): scripts/start_server.sh changed (sha $CUR)"; exit 1
fi
[ -f "$CD/scripts_at_launch.tgz" ] || tar czf "$CD/scripts_at_launch.tgz" --exclude='__pycache__' -C "$AC" scripts

probe() {   # <manifest label> <server arm> <host GB> <engine>
  local L=$1 A=$2 G=$3 E=$4 LOG IOS rc CMP
  grep -q "^$L " "$CD/manifest.txt" && { echo "C24 $L already done"; return 0; }
  LOG="$CD/driver_${L}_$(date -u +%m%d_%H%M%S).log"
  nohup iostat -dxt vdc 10 >> "$CD/iostat_vdc.log" 2>&1 < /dev/null & IOS=$!
  echo "C24 $L LAUNCH $(date -u +%FT%TZ) arm $A host $G GB engine $E -> $LOG"
  ARMS="$A" LEVEL=NAT160 HOST_GB="$G" MODEL=Qwen/Qwen3-30B-A3B-Instruct-2507 CTX=131072 KV_DTYPE=auto TEMPLATE= L3_CLEANER_PCT=70,60 \
    TRACE="$AC/traces/lmcache_agentic_trace_262k.json" USERS=768 TURNS=50 ARRIVAL=0.1 GAP=10 C=44 SEED=0 \
    ORACLE_HINTS=1 HINTS=oracle CLIENT_TIMEOUT=4500 SGLANG_TIMEOUT_KEEP_ALIVE=3600 ENGINE_PYTHONPATH="$E" \
    bash run_compare.sh > "$LOG" 2>&1
  rc=$?
  kill "$IOS" 2>/dev/null
  CMP=$(grep -a '^compare dir: ' "$LOG" | cut -d' ' -f3)
  if [ -n "$CMP" ] && [ -s "$CMP/manifest.txt" ]; then
    awk -v L="$L" 'NR == 1 { print L, $2, $3 }' "$CMP/manifest.txt" >> "$CD/manifest.txt"
    echo "C24 $L DONE $(date -u +%FT%TZ) rc=$rc compare dir $CMP"
  else
    echo "C24 $L STOP $(date -u +%FT%TZ) rc=$rc, no manifest: read $LOG"; return 1
  fi
}

probe jit_70 three_tier_wc_oracle_v2_nu_jit 70 "$JIT_ENGINE" \
  && probe horizon_90 three_tier_wc_oracle_v2_nu 90 "$V2_ENGINE" \
  && echo "C24 ALL DONE $(date -u +%FT%TZ)"
